function queryFundInfo(n,t){$.ajax({async:!1,url:"/WeixinService/business/queryFundInfo.xhtml",data:{fundId:n,period:t},dataType:"json",type:"post",cache:!1,error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){if(n.returnCode=="0000")if(n.quesList!=null){var t=n.quesList;$.each(t,function(n,t){var i="<div class='box box-FAQ'><h2><span>"+t.wWenti+"<\/span><\/h2><div class='box-text'><p>"+t.wDaan+"<\/p><\/div><\/div>";$("#FAQSection").append(i)});$("#FAQSection").html().trim()!=""&&$("#FAQSection div:last").append("<div class='more' onclick='toBack();'><a class='comeback-pro'>返回查看产品信息<\/a><\/div>")}else errorRemark("当前产品不存在"),window.location.href="/WeixinService/business/query/fundList.shtml";else errorRemark(n.returnMsg)}})}var myScroll;$(document).ready(function(){$(".header .top-a h2").html("常见问题");document.title="常见问题";myScroll=new IScroll("#wrapper",{scrollbars:!0,mouseWheel:!0,interactiveScrollbars:!0,shrinkScrollbars:"scale",fadeScrollbars:!0});var n=getUrlParameter("fundId"),t=getUrlParameter("period");n=n.replace("#","");t=t.replace("#","");queryFundInfo(n,t);myScroll.refresh();getUserRequest("FAQ")});document.addEventListener("touchmove",function(n){n.preventDefault()},!1)